import selfies as sf
from rdkit import Chem
parts='[C][C][Branch1][C][C][C][Br].[O][C][C][C][=C][C][=C][Branch1][C][Br][C][=C][Ring1][#Branch1].[C][S][Branch1][C][C][=O].[O].[K+1].[OH1-1]'.split('.')
print('Plan status: [✓] Confirmed SELFIES/RDKit available; [ ] Decode structures; [ ] Analyze reaction; [ ] State product.')
for p in parts:
 try:
  s=sf.decoder(p)
  m=Chem.MolFromSmiles(s)
  print(p, '=>', s, '|', Chem.MolToSmiles(m) if m else 'parse failed')
 except Exception as e: print(p,'ERROR',repr(e))
